def transform(grid):
    h, w = len(grid), len(grid[0])
    freq = [sum(row.count(c) for row in grid) for c in range(10)]
    candidates = []

    for r, row in enumerate(grid):
        if row[0] != 0 and all(x == row[0] for x in row):
            candidates.append((freq[row[0]], "h", r))
    for c in range(w):
        color = grid[0][c]
        if color != 0 and all(grid[r][c] == color for r in range(h)):
            candidates.append((freq[color], "v", c))

    if not candidates:
        return [row[:] for row in grid]

    _, direction, pos = min(candidates)
    if direction == "h":
        top, bottom = grid[:pos], grid[pos + 1:]
        n = min(len(top), len(bottom))
        return [[2 if top[i][j] != 0 and bottom[i][j] != 0 else 0
                 for j in range(w)] for i in range(n)]

    n = min(pos, w - pos - 1)
    return [[2 if grid[r][j] != 0 and grid[r][pos + 1 + j] != 0 else 0
             for j in range(n)] for r in range(h)]
